function parseThresholds(thresholdStrs?: string[]): { [metric: string]: number } | null {
  if (!thresholdStrs || !thresholdStrs.length) return null;

  const thresholds: { [metric: string]: number } = {};
  for (const str of thresholdStrs) {
    const parts = str.split('=');
    if (parts.length !== 2) {
      throw new Error(`Malformed threshold: "${str}" (expected format: metric=number)`);
    }
    const [metric, minStr] = parts;
    if (!metric) {
      throw new Error(`Malformed threshold: "${str}" (metric name is empty)`);
    }
    const min = parseFloat(minStr);
    if (isNaN(min)) {
      throw new Error(`Malformed threshold: "${str}" (minimum is not a number)`);
    }
    if (min < 0 || min > 1) {
      throw new Error(`Malformed threshold: "${str}" (minimum must be between 0 and 1)`);
    }
    thresholds[metric] = min;
  }
  return thresholds;
}

function getValidMetricIds(evaluations: any[]): string[] {
  return evaluations.map((eval: any) => eval.id).filter((id: string) => typeof id === 'string');
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: { [metric: string]: number } | null = null;
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    log.error((error as Error).message);
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  if (thresholds) {
    const validMetrics = getValidMetricIds(evaluations);
    for (const metric of Object.keys(thresholds)) {
      if (!validMetrics.includes(metric)) {
        log.error(`Unknown metric: "${metric}". Valid metrics: ${validMetrics.join(', ')}`);
        process.exit(2);
      }
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && report.passed === false) {
    process.exit(1);
