export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && typeof thresholds === 'object' && Object.keys(thresholds).length > 0) {
    const thresholdsArray = [];
    let allPassed = true;

    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = evaluations.find(m => m.id === metricId);
      const score = metric?.score ?? null;
      const passed = score !== null && score >= min;

      thresholdsArray.push({
        metric: metricId,
        min,
        score,
        passed
      });

      if (!passed) {
        allPassed = false;
      }
    }

    report.passed = allPassed;
    report.thresholds = thresholdsArray;
  }

  return report;
}

