3	export function toJson(report) {
4	  return JSON.stringify(report, null, 2);
5	}
6	
7	export function toMarkdown(report) {
8	  const lines = [];
9	  lines.push('# FRAI Evaluation Report');
10	  lines.push('');
11	  lines.push(`- **Generated At:** ${report.metadata.generatedAt}`);
12	  lines.push(`- **Outputs File:** ${report.metadata.outputsPath}`);
13	  if (report.metadata.referencesPath) {
14	    lines.push(`- **References File:** ${report.metadata.referencesPath}`);
15	  }
16	  lines.push(`- **Total Samples:** ${report.metadata.totalSamples}`);
17	  lines.push('');
18	
19	  if (report.thresholds && report.thresholds.length > 0) {
20	    lines.push('## Thresholds');
21	    lines.push('');
22	    report.thresholds.forEach((threshold) => {
23	      const status = threshold.passed ? 'PASS' : 'FAIL';
24	      const score = threshold.score !== null ? threshold.score : 'n/a';
25	      lines.push(`- **${threshold.metric}:** ${status} (minimum: ${threshold.min}, score: ${score})`);
26	    });
27	    lines.push('');
28	  }
29	
30	  lines.push('## Metrics');
31	  lines.push('');
32	  report.metrics.forEach((metric) => {
33	    lines.push(`### ${metric.label}`);
34	    lines.push('');
35	    lines.push(`- **Score:** ${metric.score ?? 'n/a'}`);
36	    if (typeof metric.total === 'number') {
37	      lines.push(`- **Total Samples:** ${metric.total}`);
38	    }
39	    if (typeof metric.matches === 'number') {
40	      lines.push(`- **Matches:** ${metric.matches}`);
41	    }
42	    if (typeof metric.flagged === 'number') {
43	      lines.push(`- **Flagged Samples:** ${metric.flagged}`);
44	    }
45	    if (typeof metric.averageDelta === 'number') {
46	      lines.push(`- **Average Delta:** ${metric.averageDelta}`);
47	    }
48	    lines.push('');
49	  });
50	  lines.push('---');
51	  lines.push('*Generated by FRAI Evaluation Harness*');
52	  return lines.join('\n');
53	}
54	
55	export function resolveReportPath(reportPath, format = 'json') {
56	  if (!reportPath) {
57	    return format === 'markdown' ? path.resolve('frai-eval-report.md') : path.resolve('frai-eval-report.json');
58	  }
59	  const ext = path.extname(reportPath);
60	  if (!ext) {
61	    return format === 'markdown' ? `${reportPath}.md` : `${reportPath}.json`;
62	  }
63	  return reportPath;
64	}
65	
66	export default {
67	  toJson,
68	  toMarkdown,
69	  resolveReportPath
70	};
