// Quick test of threshold parsing logic
function parseThresholds(thresholdStrs) {
  if (!thresholdStrs || !thresholdStrs.length) return null;

  const thresholds = {};
  for (const str of thresholdStrs) {
    const parts = str.split('=');
    if (parts.length !== 2) {
      throw new Error(`Malformed threshold: "${str}" (expected format: metric=number)`);
    }
    const [metric, minStr] = parts;
    if (!metric) {
      throw new Error(`Malformed threshold: "${str}" (metric name is empty)`);
    }
    const min = parseFloat(minStr);
    if (isNaN(min)) {
      throw new Error(`Malformed threshold: "${str}" (minimum is not a number)`);
    }
    if (min < 0 || min > 1) {
      throw new Error(`Malformed threshold: "${str}" (minimum must be between 0 and 1)`);
    }
    thresholds[metric] = min;
  }
  return thresholds;
}

// Test cases
console.log('Test 1: Valid threshold');
console.log(parseThresholds(['exact_match=0.9'])); // { exact_match: 0.9 }

console.log('\nTest 2: Multiple thresholds');
console.log(parseThresholds(['exact_match=0.9', 'toxicity=0.95'])); // { exact_match: 0.9, toxicity: 0.95 }

console.log('\nTest 3: No threshold');
console.log(parseThresholds(undefined)); // null

console.log('\nTest 4: Empty array');
console.log(parseThresholds([])); // null

try {
  console.log('\nTest 5: Malformed threshold (missing =)');
  parseThresholds(['exact_match']);
} catch (e) {
  console.error('Error:', e.message);
}

try {
  console.log('\nTest 6: Invalid minimum (>1)');
  parseThresholds(['exact_match=1.5']);
} catch (e) {
  console.error('Error:', e.message);
}

try {
  console.log('\nTest 7: Invalid minimum (<0)');
  parseThresholds(['exact_match=-0.1']);
} catch (e) {
  console.error('Error:', e.message);
}
